 1→import { test, expect } from '@playwright/test';
 2→
 3→const VALID_NOTES = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
 4→
 5→test.describe('Fretboard Flash game loop: note appears, answer shown on fretboard, next note', () => {
 6→  test('should cycle through SHOW_NOTE, SHOW_ANSWER, and advance to the next note', async ({ page }) => {
 7→    // Navigate to the Fretboard Flash game page
 8→    await page.goto('/learn/fretboard-flash');
 9→    const gamePage = page.getByTestId('fretboard-flash-page');
10→    await expect(gamePage).toBeVisible();
11→
12→    // The game starts in IDLE state: Start button visible, no note displayed, no marker
13→    const startButton = page.getByTestId('start-button');
14→    await expect(startButton).toBeVisible();
15→    await expect(page.getByTestId('note-display')).not.toBeVisible();
16→    await expect(page.getByTestId('note-marker')).not.toBeVisible();
17→
18→    // --- Step 1: Start the game ---
19→    await startButton.click();
20→
21→    // SHOW_NOTE state: note letter appears, start button is replaced by stop button
22→    const noteDisplay = page.getByTestId('note-display');
23→    await expect(noteDisplay).toBeVisible();
24→    await expect(page.getByTestId('stop-button')).toBeVisible();
25→
26→    // The displayed note must be a valid natural note
27→    const firstNote = (await noteDisplay.textContent())!.trim();
28→    expect(VALID_NOTES).toContain(firstNote);
29→
30→    // During SHOW_NOTE, the fretboard marker should NOT be visible yet
31→    await expect(page.getByTestId('note-marker')).not.toBeVisible();
32→
33→    // --- Step 2: Wait for SHOW_ANSWER state (after ~5 seconds) ---
34→    // The note marker appears on the fretboard when the answer is shown
35→    const noteMarker = page.getByTestId('note-marker');
36→    await expect(noteMarker).toBeVisible({ timeout: 7000 });
37→
38→    // The note letter should still be displayed during SHOW_ANSWER
39→    await expect(noteDisplay).toBeVisible();
40→    const noteStillShown = (await noteDisplay.textContent())!.trim();
41→    expect(noteStillShown).toBe(firstNote);
42→
43→    // --- Step 3: Wait for next note (after ~3 more seconds, the cycle advances) ---
44→    // The marker should disappear as we transition back to SHOW_NOTE with a new note
45→    await expect(noteMarker).not.toBeVisible({ timeout: 5000 });
46→
47→    // A note letter should still be displayed (the next note in the cycle)
48→    await expect(noteDisplay).toBeVisible();
49→
50→    // The game is still running: stop button should remain visible
51→    await expect(page.getByTestId('stop-button')).toBeVisible();
52→  });
53→});
