import { test, expect } from '@playwright/test';

/**
 * Open string notes (fret 0): E, A, D, G, B, E
 * Fret 1 natural notes: F (string 1), C (string 2)
 *
 * The unique note NAMES that only appear starting from fret 1 are F and C.
 * If the note display ever shows "F" or "C", we know the pool has expanded
 * beyond open strings.
 */
const OPEN_STRING_NOTE_NAMES = new Set(['E', 'A', 'D', 'G', 'B']);
const FRET_1_ONLY_NOTES = new Set(['F', 'C']);

test.describe('Fretboard Flash progression: pool expands after all open notes are shown', () => {
  test('should start with open string notes and expand to fret 1 after all open notes seen', async ({ page }) => {
    // Install fake timers so we can fast-forward through the game loop
    await page.clock.install();

    await page.goto('/learn/fretboard-flash');
    await expect(page.getByTestId('fretboard-flash-page')).toBeVisible();

    // The current fret indicator should show fret 0 at the start
    const currentFretDisplay = page.getByTestId('current-fret');

    // Start the game
    await page.getByTestId('start-button').click();

    // Verify the game starts at fret 0
    await expect(currentFretDisplay).toHaveText('0');

    // Collect notes by cycling through the game loop quickly.
    // Each cycle: 5000ms SHOW_NOTE + 3000ms SHOW_ANSWER = 8000ms
    // With 6 open string notes and random selection, we need enough cycles
    // to statistically see all 6 unique notes. We'll run up to 60 cycles
    // (the coupon collector expected value for 6 items is ~14.7, so 60 is
    // very safe).
    const seenNotes = new Set<string>();
    let expandedToFret1 = false;

    for (let cycle = 0; cycle < 60; cycle++) {
      // Read the current note in SHOW_NOTE state
      const noteDisplay = page.getByTestId('note-display');
      await expect(noteDisplay).toBeVisible();
      const noteName = (await noteDisplay.textContent())!.trim();

      // If we see F or C, that means the pool has expanded to fret 1
      if (FRET_1_ONLY_NOTES.has(noteName)) {
        expandedToFret1 = true;
        break;
      }

      seenNotes.add(noteName);

      // Fast-forward through SHOW_NOTE (5s) + SHOW_ANSWER (3s) to get to next note
      await page.clock.fastForward(5000);
      await page.clock.fastForward(3000);
    }

    // After the loop, the pool should have expanded: either we saw F/C directly,
    // or the current fret indicator shows we moved past fret 0
    if (!expandedToFret1) {
      // If we somehow didn't see F or C in the note display, check the fret indicator
      const fretText = await currentFretDisplay.textContent();
      const currentFret = parseInt(fretText!.trim(), 10);
      expect(currentFret).toBeGreaterThanOrEqual(1);
    }

    // Verify the fret indicator confirms expansion
    const fretText = await currentFretDisplay.textContent();
    const finalFret = parseInt(fretText!.trim(), 10);
    expect(finalFret).toBeGreaterThanOrEqual(1);
  });
});

