 1→import { inject, Injectable } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { NoteDataService } from './note-data.service';
 4→
 5→const MAX_FRET = 15;
 6→
 7→@Injectable()
 8→export class ProgressionService {
 9→  private readonly noteDataService = inject(NoteDataService);
10→
11→  private currentFret = 0;
12→  private pool: FretNote[] = [];
13→  private shownNoteKeys = new Set<string>();
14→
15→  constructor() {
16→    this.pool = this.noteDataService.getNotesOnFret(0);
17→  }
18→
19→  getCurrentPool(): FretNote[] {
20→    return this.pool;
21→  }
22→
23→  getCurrentFret(): number {
24→    return this.currentFret;
25→  }
26→
27→  getShownNoteCount(): number {
28→    return this.shownNoteKeys.size;
29→  }
30→
31→  drawNote(): FretNote {
32→    if (this.pool.length === 0) {
33→      throw new Error('ProgressionService: pool is empty — cannot draw note');
34→    }
35→    const index = Math.floor(Math.random() * this.pool.length);
36→    const note = this.pool[index];
37→    this.markNoteAsShown(note);
38→    return note;
39→  }
40→
41→  hasBeenShown(note: FretNote): boolean {
42→    return this.shownNoteKeys.has(this.noteKey(note));
43→  }
44→
45→  markNoteAsShown(note: FretNote): void {
46→    this.shownNoteKeys.add(this.noteKey(note));
47→
48→    if (this.shownNoteKeys.size >= this.pool.length) {
49→      this.expandPool();
50→    }
51→  }
52→
53→  reset(): void {
54→    this.currentFret = 0;
55→    this.pool = this.noteDataService.getNotesOnFret(0);
56→    this.shownNoteKeys.clear();
57→  }
58→
59→  private expandPool(): void {
60→    let nextFret = this.currentFret + 1;
61→
62→    while (nextFret <= MAX_FRET) {
63→      const newNotes = this.noteDataService.getNotesOnFret(nextFret);
64→      if (newNotes.length > 0) {
65→        this.currentFret = nextFret;
66→        this.pool = this.noteDataService.getNotesUpToFret(nextFret);
67→        this.shownNoteKeys.clear();
68→        return;
69→      }
70→      nextFret++;
71→    }
72→
73→    // Already at max — reset shown tracking so the game continues cycling
74→    this.shownNoteKeys.clear();
75→  }
76→
77→  private noteKey(note: FretNote): string {
78→    return `${note.string}-${note.fret}`;
79→  }
80→}
81→

 1→import { inject, Injectable, OnDestroy, signal } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { ProgressionService } from './progression.service';
 4→
 5→export enum GameState {
 6→  IDLE = 'IDLE',
 7→  SHOW_NOTE = 'SHOW_NOTE',
 8→  SHOW_ANSWER = 'SHOW_ANSWER',
 9→}
10→
11→export const SHOW_NOTE_DURATION_MS = 5000;
12→export const SHOW_ANSWER_DURATION_MS = 3000;
13→
14→/**
15→ * Manages the fretboard flash game state machine (IDLE -> SHOW_NOTE -> SHOW_ANSWER cycle).
16→ *
17→ * This service must remain component-provided (not `providedIn: 'root'`) because it
18→ * implements OnDestroy to clean up timers, which only fires for component-scoped providers.
19→ */
20→@Injectable()
21→export class GameStateService implements OnDestroy {
22→  private readonly progression = inject(ProgressionService);
23→
24→  private readonly _state = signal<GameState>(GameState.IDLE);
25→  private readonly _currentNote = signal<FretNote | null>(null);
26→  private timerId: ReturnType<typeof setTimeout> | null = null;
27→
28→  readonly state = this._state.asReadonly();
29→  readonly currentNote = this._currentNote.asReadonly();
30→
31→  start(): void {
32→    if (this._state() !== GameState.IDLE) {
33→      return;
34→    }
35→    this._currentNote.set(this.progression.drawNote());
36→    this._state.set(GameState.SHOW_NOTE);
37→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
38→  }
39→
40→  showAnswer(): void {
41→    if (this._state() !== GameState.SHOW_NOTE) {
42→      return;
43→    }
44→    this.clearTimer();
45→    this._state.set(GameState.SHOW_ANSWER);
46→    this.startTimer(SHOW_ANSWER_DURATION_MS, () => this.nextNote());
47→  }
48→
49→  nextNote(): void {
50→    if (this._state() !== GameState.SHOW_ANSWER) {
51→      return;
52→    }
53→    this.clearTimer();
54→    this._currentNote.set(this.progression.drawNote());
55→    this._state.set(GameState.SHOW_NOTE);
56→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
57→  }
58→
59→  stop(): void {
60→    this.clearTimer();
61→    this._currentNote.set(null);
62→    this._state.set(GameState.IDLE);
63→    this.progression.reset();
64→  }
65→
66→  ngOnDestroy(): void {
67→    this.clearTimer();
68→  }
69→
70→  private startTimer(durationMs: number, callback: () => void): void {
71→    this.clearTimer();
72→    this.timerId = setTimeout(callback, durationMs);
73→  }
74→
75→  private clearTimer(): void {
76→    if (this.timerId !== null) {
77→      clearTimeout(this.timerId);
78→      this.timerId = null;
79→    }
80→  }
81→}
82→

