 1→import { test, expect } from '@playwright/test';
 2→
 3→/**
 4→ * Open string notes (fret 0): E, A, D, G, B, E (6 notes, 5 unique names).
 5→ * Fret 1 natural notes: F (string 1, high E + 1 semitone) and C (string 2, B + 1 semitone).
 6→ *
 7→ * F and C never appear on open strings, so seeing either in the note display
 8→ * proves the pool has expanded beyond fret 0.
 9→ */
10→const FRET_1_ONLY_NOTES = new Set(['F', 'C']);
11→
12→test.describe('Fretboard Flash progression: pool expands after all open notes are shown', () => {
13→  test('should start at fret 0 and expand to fret 1 after cycling through open notes', async ({ page }) => {
14→    // Use fake timers to fast-forward through the 5s note + 3s answer cycle
15→    await page.clock.install();
16→
17→    await page.goto('/learn/fretboard-flash');
18→    await expect(page.getByTestId('fretboard-flash-page')).toBeVisible();
19→
20→    const currentFretDisplay = page.getByTestId('current-fret');
21→
22→    // Start the game
23→    await page.getByTestId('start-button').click();
24→
25→    // Game starts with open strings only (fret 0)
26→    await expect(currentFretDisplay).toHaveText('0');
27→
28→    // Fast-forward through enough cycles for all 6 open notes to be drawn randomly.
29→    // Coupon collector problem: expected ~14.7 draws for 6 items; 60 cycles gives
30→    // near-certain coverage even with unlucky random draws.
31→    let expandedToFret1 = false;
32→
33→    for (let cycle = 0; cycle < 60; cycle++) {
34→      const noteDisplay = page.getByTestId('note-display');
35→      await expect(noteDisplay).toBeVisible();
36→      const noteName = (await noteDisplay.textContent())!.trim();
37→
38→      // F or C only exist from fret 1 onward, so seeing one proves expansion
39→      if (FRET_1_ONLY_NOTES.has(noteName)) {
40→        expandedToFret1 = true;
41→        break;
42→      }
43→
44→      // Advance through SHOW_NOTE (5s) then SHOW_ANSWER (3s) to reach next cycle
45→      await page.clock.fastForward(5000);
46→      await page.clock.fastForward(3000);
47→    }
48→
49→    // Verify the pool expanded: the fret indicator must have moved past 0
50→    const finalFret = parseInt((await currentFretDisplay.textContent())!.trim(), 10);
51→    expect(finalFret).toBeGreaterThanOrEqual(1);
52→
53→    // At least one fret-1-only note (F or C) should have appeared, confirming
54→    // the progression system added higher-fret notes to the pool
55→    expect(expandedToFret1).toBe(true);
56→  });
57→});
58→

 1→import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
 2→import { GameState, GameStateService } from '../game-state.service';
 3→import { ProgressionService } from '../progression.service';
 4→import { NoteDataService } from '../note-data.service';
 5→import { FretboardDisplayComponent } from '../fretboard-display/fretboard-display';
 6→
 7→@Component({
 8→  selector: 'app-fretboard-flash-page',
 9→  templateUrl: './fretboard-flash-page.html',
10→  styleUrl: './fretboard-flash-page.scss',
11→  changeDetection: ChangeDetectionStrategy.OnPush,
12→  imports: [FretboardDisplayComponent],
13→  providers: [GameStateService, ProgressionService, NoteDataService],
14→})
15→export class FretboardFlashPageComponent {
16→  private readonly gameState = inject(GameStateService);
17→  private readonly progression = inject(ProgressionService);
18→
19→  readonly state = this.gameState.state;
20→  readonly currentNote = this.gameState.currentNote;
21→  readonly isIdle = computed(() => this.state() === GameState.IDLE);
22→  readonly isShowAnswer = computed(() => this.state() === GameState.SHOW_ANSWER);
23→  readonly fretboardNote = computed(() => this.isShowAnswer() ? this.currentNote() : null);
24→  readonly currentFret = computed(() => {
25→    // Re-evaluate whenever the current note changes (each draw triggers a state change)
26→    this.currentNote();
27→    return this.progression.getCurrentFret();
28→  });
29→
30→  start(): void {
31→    this.gameState.start();
32→  }
33→
34→  stop(): void {
35→    this.gameState.stop();
36→  }
37→}
38→

 1→import { inject, Injectable } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { NoteDataService } from './note-data.service';
 4→
 5→const MAX_FRET = 15;
 6→
 7→@Injectable()
 8→export class ProgressionService {
 9→  private readonly noteDataService = inject(NoteDataService);
10→
11→  private currentFret = 0;
12→  private pool: FretNote[] = [];
13→  private shownNoteKeys = new Set<string>();
14→
15→  constructor() {
16→    this.pool = this.noteDataService.getNotesOnFret(0);
17→  }
18→
19→  getCurrentPool(): FretNote[] {
20→    return this.pool;
21→  }
22→
23→  getCurrentFret(): number {
24→    return this.currentFret;
25→  }
26→
27→  getShownNoteCount(): number {
28→    return this.shownNoteKeys.size;
29→  }
30→
31→  drawNote(): FretNote {
32→    if (this.pool.length === 0) {
33→      throw new Error('ProgressionService: pool is empty — cannot draw note');
34→    }
35→    const index = Math.floor(Math.random() * this.pool.length);
36→    const note = this.pool[index];
37→    this.markNoteAsShown(note);
38→    return note;
39→  }
40→
41→  hasBeenShown(note: FretNote): boolean {
42→    return this.shownNoteKeys.has(this.noteKey(note));
43→  }
44→
45→  markNoteAsShown(note: FretNote): void {
46→    this.shownNoteKeys.add(this.noteKey(note));
47→
48→    if (this.shownNoteKeys.size >= this.pool.length) {
49→      this.expandPool();
50→    }
51→  }
52→
53→  reset(): void {
54→    this.currentFret = 0;
55→    this.pool = this.noteDataService.getNotesOnFret(0);
56→    this.shownNoteKeys.clear();
57→  }
58→
59→  private expandPool(): void {
60→    let nextFret = this.currentFret + 1;
61→
62→    while (nextFret <= MAX_FRET) {
63→      const newNotes = this.noteDataService.getNotesOnFret(nextFret);
64→      if (newNotes.length > 0) {
65→        this.currentFret = nextFret;
66→        this.pool = this.noteDataService.getNotesUpToFret(nextFret);
67→        this.shownNoteKeys.clear();
68→        return;
69→      }
70→      nextFret++;
71→    }
72→
73→    // Already at max — reset shown tracking so the game continues cycling
74→    this.shownNoteKeys.clear();
75→  }
76→
77→  private noteKey(note: FretNote): string {
78→    return `${note.string}-${note.fret}`;
79→  }
80→}
81→

 1→import { inject, Injectable, OnDestroy, signal } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { ProgressionService } from './progression.service';
 4→
 5→export enum GameState {
 6→  IDLE = 'IDLE',
 7→  SHOW_NOTE = 'SHOW_NOTE',
 8→  SHOW_ANSWER = 'SHOW_ANSWER',
 9→}
10→
11→export const SHOW_NOTE_DURATION_MS = 5000;
12→export const SHOW_ANSWER_DURATION_MS = 3000;
13→
14→/**
15→ * Manages the fretboard flash game state machine (IDLE -> SHOW_NOTE -> SHOW_ANSWER cycle).
16→ *
17→ * This service must remain component-provided (not `providedIn: 'root'`) because it
18→ * implements OnDestroy to clean up timers, which only fires for component-scoped providers.
19→ */
20→@Injectable()
21→export class GameStateService implements OnDestroy {
22→  private readonly progression = inject(ProgressionService);
23→
24→  private readonly _state = signal<GameState>(GameState.IDLE);
25→  private readonly _currentNote = signal<FretNote | null>(null);
26→  private timerId: ReturnType<typeof setTimeout> | null = null;
27→
28→  readonly state = this._state.asReadonly();
29→  readonly currentNote = this._currentNote.asReadonly();
30→
31→  start(): void {
32→    if (this._state() !== GameState.IDLE) {
33→      return;
34→    }
35→    this._currentNote.set(this.progression.drawNote());
36→    this._state.set(GameState.SHOW_NOTE);
37→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
38→  }
39→
40→  showAnswer(): void {
41→    if (this._state() !== GameState.SHOW_NOTE) {
42→      return;
43→    }
44→    this.clearTimer();
45→    this._state.set(GameState.SHOW_ANSWER);
46→    this.startTimer(SHOW_ANSWER_DURATION_MS, () => this.nextNote());
47→  }
48→
49→  nextNote(): void {
50→    if (this._state() !== GameState.SHOW_ANSWER) {
51→      return;
52→    }
53→    this.clearTimer();
54→    this._currentNote.set(this.progression.drawNote());
55→    this._state.set(GameState.SHOW_NOTE);
56→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
57→  }
58→
59→  stop(): void {
60→    this.clearTimer();
61→    this._currentNote.set(null);
62→    this._state.set(GameState.IDLE);
63→    this.progression.reset();
64→  }
65→
66→  ngOnDestroy(): void {
67→    this.clearTimer();
68→  }
69→
70→  private startTimer(durationMs: number, callback: () => void): void {
71→    this.clearTimer();
72→    this.timerId = setTimeout(callback, durationMs);
73→  }
74→
75→  private clearTimer(): void {
76→    if (this.timerId !== null) {
77→      clearTimeout(this.timerId);
78→      this.timerId = null;
79→    }
80→  }
81→}
